<style>
.arc-ag{background:#18283b;color:#e9f2ff;min-height:0;flex:1 1 auto;padding:0;font:12px 'Segoe UI',Arial,sans-serif}.arc-ag *{box-sizing:border-box}.arc-ag [hidden]{display:none!important}.arc-ag-toolbar{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.arc-ag :is(input,select){border:1px solid #415671;border-radius:6px;background:#192a3f;color:#ecf5ff;padding:8px;min-width:0}.arc-ag-toolbar input[type=search]{flex:1;min-width:130px}.arc-ag button{border:1px solid #435a72;border-radius:7px;background:#24374e;color:#fff;padding:8px 12px;cursor:pointer}.arc-ag button.primary{background:#b7806c;border-color:#b7806c}.arc-ag-table-wrap{overflow:auto;margin:10px;max-height:calc(100dvh - 350px);border:1px solid #344a62;border-radius:8px}.arc-ag table{width:100%;border-collapse:collapse;min-width:690px;text-align:left}.arc-ag th{position:sticky;top:0;background:#24374e}.arc-ag td,.arc-ag th{padding:11px;border-bottom:1px solid #31475f}.arc-ag-actions{display:flex;gap:5px}.arc-ag-modal{background:#1c3047;color:#ecf5ff;border:1px solid #3f5b77;border-radius:10px;width:min(570px,calc(100vw - 24px));max-height:85dvh;overflow:auto;padding:0}.arc-ag-modal::backdrop{background:#071321ba}.arc-ag-modal header{display:flex;justify-content:space-between;align-items:center;padding:11px 14px;background:#263e57}.arc-ag-modal header h2{font-size:15px;margin:0}.arc-ag-form{padding:15px;display:grid;gap:10px}.arc-ag-form label{display:grid;gap:5px}.arc-ag-form fieldset{display:flex;flex-wrap:wrap;gap:12px;border:1px solid #435a72}.arc-ag-form fieldset label,.arc-ag-inline{display:flex!important;align-items:center;gap:6px}.arc-ag-foot{display:flex;justify-content:flex-end;gap:7px}.arc-ag-status{padding:8px 0;color:#aed4e6}.arc-ag-history{padding:13px;display:grid;gap:8px}.arc-ag-history article{padding:10px;border-bottom:1px solid #42536a}
</style>
<section class="arc-ag" id="arc-ag" data-base="<?=arc_h(arc_workspace_base_url())?>" data-network="<?=$networkId?>" data-manage="<?=$canManageSchedules?'1':'0'?>" data-csrf="<?=arc_h($csrf)?>">
<div class="arc-ag-toolbar"><input type="hidden" id="ag-gestor" value="<?=(int)$selectedGestorId?>"><input type="search" id="ag-search" placeholder="Buscar rotina" aria-label="Buscar rotina"><select id="ag-filter" aria-label="Situação"><option value="all">Todas</option><option value="active">Ativas</option><option value="inactive">Encerradas</option></select><button id="ag-refresh" type="button" title="Atualizar">Atualizar</button><button id="ag-new" type="button" class="primary" <?=$canManageSchedules?'':'disabled'?>>Nova rotina</button></div>
