<dialog id="ag-editor" class="arc-ag-modal"><header><h2 id="ag-title">Nova rotina</h2><button type="button" data-close="editor" aria-label="Fechar">×</button></header><form id="ag-form" class="arc-ag-form"><label>Serviço<select name="command" required><?php foreach(arc_support_schedule_actions() as $command=>$label):?><option value="<?=arc_h($command)?>"><?=arc_h($label)?></option><?php endforeach;?></select></label><label>Início<input type="datetime-local" name="starts_at" required></label><label>Repetir<select name="recurrence"><option value="once">Uma vez</option><option value="weekdays">Dias da semana</option><option value="interval">A cada intervalo</option></select></label><label id="ag-interval" hidden>Intervalo em minutos<input type="number" name="interval_minutes" min="15" max="10080" value="60"></label><fieldset id="ag-weekdays" hidden><legend>Dias da semana</legend><?php foreach([1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',7=>'Dom'] as $day=>$label):?><label><input type="checkbox" name="weekdays" value="<?=$day?>"> <?=$label?></label><?php endforeach;?></fieldset><label>Data de término (opcional)<input type="datetime-local" name="ends_at"></label><label id="ag-password" hidden>Senha da sua conta<input type="password" name="password" autocomplete="current-password"></label><label id="ag-confirm" hidden class="arc-ag-inline"><input type="checkbox" name="confirmed"> Confirmo a operação</label><div class="arc-ag-foot"><button type="button" data-close="editor">Cancelar</button><button type="submit" class="primary">Salvar</button></div></form></dialog>
