</section>
<script>
(()=>{'use strict';const root=document.getElementById('arc-ag');if(!root)return;const $=id=>document.getElementById('ag-'+id),form=$('form'),editor=$('editor'),history=$('history'),selector=$('gestor');const network=Number(root.dataset.network),csrf=root.dataset.csrf,base=root.dataset.base,canManage=root.dataset.manage==='1';const labels=<?=json_encode(arc_support_schedule_actions(),JSON_UNESCAPED_UNICODE)?>;let rows=[],runs=[],editId=0,busy=false;
async function api(action,data={}){const r=await fetch(base+'api/support.php?action=schedule-'+action,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({network_id:network,gestor_id:Number(selector.value),...data})});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Não foi possível concluir a operação.');return j;}
function date(s){return s?String(s).replace('T',' ').slice(0,16):'—'}
function recurrence(r){return r.recurrence==='once'?'Uma vez':r.recurrence==='interval'?'A cada '+r.interval_minutes+' min':'Dias: '+(r.weekdays||'—')}
function fields(){const rec=form.elements.recurrence.value,energy=form.elements.command.value.startsWith('power_');$('interval').hidden=rec!=='interval';$('weekdays').hidden=rec!=='weekdays';$('password').hidden=!energy;$('confirm').hidden=!energy;}
function render(){const term=$('search').value.trim().toLowerCase(),filter=$('filter').value,body=$('rows');body.replaceChildren();for(const row of rows){const active=Number(row.enabled)&&!!row.next_run_at;if((filter==='active'&&!active)||(filter==='inactive'&&active))continue;if(term&&!String(labels[row.command_name]||row.command_name).toLowerCase().includes(term))continue;const tr=document.createElement('tr');[labels[row.command_name]||row.command_name,recurrence(row),date(row.next_run_at),active?'Ativo':Number(row.enabled)?'Encerrado':'Cancelado'].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});const td=document.createElement('td'),actions=document.createElement('div');actions.className='arc-ag-actions';const btn=(name,callback)=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.addEventListener('click',callback);actions.append(b)};btn('Histórico',()=>showHistory(row));if(canManage&&Number(row.enabled)){btn('Editar',()=>openEditor(row));btn('Cancelar',()=>cancel(row))}td.append(actions);tr.append(td);body.append(tr)}if(!body.childElementCount){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='Nenhuma rotina para os filtros selecionados.';tr.append(td);body.append(tr)}}
async function refresh(){try{const j=await api('list');rows=j.schedules||[];runs=j.runs||[];$('status').textContent=rows.length+' rotina(s) encontrada(s).';render()}catch(e){$('status').textContent=e.message}}
function openEditor(row){if(!canManage||!Number(selector.value))return;editId=Number(row?.id||0);form.reset();$('title').textContent=editId?'Editar rotina #'+editId:'Nova rotina';if(row){form.elements.command.value=row.command_name;form.elements.recurrence.value=row.recurrence;form.elements.starts_at.value=date(row.starts_at||row.next_run_at).replace(' ','T');form.elements.ends_at.value=date(row.ends_at).replace('—','').replace(' ','T');form.elements.interval_minutes.value=row.interval_minutes||60;form.querySelectorAll('[name=weekdays]').forEach(i=>i.checked=String(row.weekdays||'').split(',').includes(i.value))}else{const d=new Date(Date.now()+300000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());form.elements.starts_at.value=d.toISOString().slice(0,16)}fields();editor.showModal()}
function showHistory(row){const target=$('history-rows');target.replaceChildren();for(const run of runs.filter(x=>Number(x.schedule_id)===Number(row.id))){const item=document.createElement('article');item.textContent=date(run.scheduled_for)+' — '+(run.task_status||run.outcome||'')+' · '+(run.result_text||run.message||'');target.append(item)}if(!target.childElementCount)target.textContent='Nenhuma execução registrada.';history.showModal()}
async function cancel(row){if(!confirm('Cancelar a rotina #'+row.id+'?'))return;try{await api('cancel',{id:Number(row.id)});await refresh()}catch(e){$('status').textContent=e.message}}
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const b=form.querySelector('[type=submit]');b.disabled=true;try{const data=Object.fromEntries(new FormData(form));data.weekdays=[...form.querySelectorAll('[name=weekdays]:checked')].map(i=>Number(i.value));data.confirmed=form.elements.confirmed.checked;if(editId)data.id=editId;await api(editId?'edit':'save',data);form.elements.password.value='';editor.close();await refresh()}catch(e){$('status').textContent=e.message}finally{busy=false;b.disabled=false}});
editor.addEventListener('close',()=>{form.elements.password.value='';});
window.addEventListener('arc-tool-refresh',event=>{if(event.detail?.tool==='agenda'&&!editor.open&&!history.open)refresh();});
form.elements.recurrence.addEventListener('change',fields);form.elements.command.addEventListener('change',fields);$('new').addEventListener('click',()=>openEditor(null));$('refresh').addEventListener('click',refresh);selector.addEventListener('change',refresh);$('search').addEventListener('input',render);$('filter').addEventListener('change',render);root.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));refresh();
})();
</script>
